SELECT e.id, e.plate_no AS plateNo, e.plate_color AS plateColor, e.space_no AS spaceNo, e.enter_time AS enterTime, e.record_type AS recordType, e.status AS status, e.station_id AS stationId, s.name AS stationName, e.remark, e.proof_image AS proofImage, e.is_corrected AS isCorrected, e.reserve1, e.reserve2, e.creator, e.updater, e.create_time AS createTime, e.update_time AS updateTime FROM enter_record e LEFT JOIN station_info s ON e.station_id = s.id WHERE e.deleted = 0
AND e.plate_no LIKE CONCAT('%', #{query.plateNo}, '%')
AND e.plate_color = #{query.plateColor}
AND e.space_no LIKE CONCAT('%', #{query.spaceNo}, '%')
AND e.enter_time BETWEEN #{query.enterTime[0]} AND #{query.enterTime[1]}
AND e.record_type = #{query.recordType}
AND e.status = #{query.status}
AND e.station_id = #{query.stationId}
AND e.remark LIKE CONCAT('%', #{query.remark}, '%')
AND e.is_corrected = #{query.isCorrected}
ORDER BY e.id DESC

SELECT DATE(t1.enter_time) AS date, COUNT(*) AS count FROM enter_record t1 WHERE t1.deleted = 0
AND t1.enter_time BETWEEN #{start} AND #{end}
AND t1.station_id = #{stationId}
GROUP BY DATE(t1.enter_time) ORDER BY DATE(t1.enter_time)

SELECT DATE_FORMAT(t1.enter_time, '%H:00') AS hour, COUNT(*) AS count FROM enter_record t1 WHERE t1.deleted = 0
AND t1.enter_time BETWEEN #{start} AND #{end}
AND t1.station_id = #{stationId}
GROUP BY DATE_FORMAT(t1.enter_time, '%H:00') ORDER BY hour

SELECT COUNT(*)
FROM enter_record t1
WHERE t1.deleted = 0
AND t1.enter_time BETWEEN #{start} AND #{end}

    AND t1.station_id = #{stationId}
